// @name Video player
// The videos in a folder of the frame's assets, one after another, for ever:
// by name or shuffled, each once or the one on show again and again. Played
// like a phone's player: a tap shows the controls (back and forward 10
// seconds, pause, the video before and after, the list, a bar to drag) and
// another hides them, as they do by themselves after a few seconds of
// playing; a double tap on the left or the right goes 10 seconds back or on;
// a swipe across the picture, or in from the screen's edge, the video after
// or before. Keys too: the arrows 10 seconds, space or K pause, N and P (or
// Page Down and Up) the next and previous video, 0 to 9 a tenth of the way
// in, L the list. Where it was is kept on disk, so a restart goes on with the
// same file. Plays on a Raspberry Pi (docs/video.md): the frames are decoded
// by ffmpeg at the size of the box, and only the video is drawn again each
// frame.
const VIDEO = /\.(mp4|m4v|mov|mkv|webm|avi|ts|mts|m2ts|mpg|mpeg|wmv|flv|3gp|ogv)$/i
const CONTROLS_MS = 4000
const FLASH_MS = 700
const SKIP_SECONDS = 10
const RESTART_AFTER = 3 // back past this many seconds in: the same video from its start
const LIST_AGAIN_MS = 60000
const SKIP_FAILED_MS = 3000

// What the folder holds: read again every minute, so new files join.
let files = []
let listedFolder = null
let listedAt = 0
let order = []
// Where it is, by file (kept on disk in the private `spot` field).
let current = ''
let paused = false
let view = 'player' // or 'list'
let controlsUntil = 0
let failed = {} // file -> why, skipped until the folder is read again
let failedAt = 0
let savedAt = 0
let restartAt = null // the file on show picked again: back to here
let video = null // the last render's video, for the keys and the handlers
let scrub = null // a finger on the bar: how far along it (0 to 1)
let flash = null // { text, side, until }: what a skip just did, on its side

const baseName = (path) => path.split('/').pop()
const clock = (s) => {
  if (!(s >= 0)) return '--:--'
  const h = Math.floor(s / 3600)
  const m = Math.floor((s % 3600) / 60)
  const sec = String(Math.floor(s % 60)).padStart(2, '0')
  return h > 0 ? `${h}:${String(m).padStart(2, '0')}:${sec}` : `${m}:${sec}`
}

const readSpot = (app) => {
  let spot = app.state.spot
  if (typeof spot === 'string') {
    try {
      spot = JSON.parse(spot)
    } catch {
      spot = null
    }
  }
  return spot && typeof spot === 'object' ? spot : {}
}

const shuffled = (list) => {
  const out = list.slice()
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1))
    const t = out[i]
    out[i] = out[j]
    out[j] = t
  }
  return out
}

const folderOf = (app) => String(app.state.folder ?? 'videos').trim().replace(/^\/+|\/+$/g, '')

function listFolder(app) {
  const folder = folderOf(app)
  const now = Date.now()
  if (listedFolder === folder && now - listedAt < LIST_AGAIN_MS) return
  // Every file below the folder, each named from the assets' top.
  const found = frameos.listAssets(folder) || []
  const before = files.join('\n')
  files = found
    .filter((name) => VIDEO.test(name) && !name.split('/').some((part) => part.startsWith('.')))
    .sort((a, b) => a.localeCompare(b, undefined, { numeric: true }))
  if (listedFolder !== folder || files.join('\n') !== before) {
    order = app.state.order === 'shuffle' ? shuffled(files) : files.slice()
    failed = {}
  }
  listedFolder = folder
  listedAt = now
}

function playable() {
  return order.filter((file) => !failed[file])
}

function step(app, by) {
  const list = playable()
  if (!list.length) return
  const at = list.indexOf(current)
  let next = at < 0 ? 0 : at + by
  if (next >= list.length) {
    // Round again, in a new order when shuffled.
    if (app.state.order === 'shuffle' && list.length > 2) order = shuffled(files)
    next = 0
  }
  if (next < 0) next = list.length - 1
  play(app, playable()[next], 0)
}

function play(app, file, start) {
  if (file === current) restartAt = start
  current = file
  paused = false
  scrub = null
  frameos.setState('spot', { file, time: start })
  savedAt = Date.now()
  frameos.remember('start', start)
}

const showControls = () => {
  controlsUntil = Date.now() + CONTROLS_MS
}
const controlsShown = () =>
  paused || scrub !== null || view !== 'player' || Date.now() < controlsUntil

const knownLength = () => !!video && video.duration > 0

function seekTo(seconds) {
  if (!knownLength()) return false
  const at = Math.max(0, Math.min(video.duration - 0.05, seconds))
  frameos.seekVideo(video, at)
  // Shown at once, before the decoder's first frame from there.
  video = { ...video, time: at }
  return true
}

function skip(by, side) {
  if (!knownLength()) return false
  seekTo((video.time ?? 0) + by)
  flash = { text: `${by > 0 ? '+' : '−'}${Math.abs(by)} s`, side, until: Date.now() + FLASH_MS }
  return true
}

// The big button in the middle says which: no flash over it.
function togglePause() {
  paused = !paused
}

// Back: the start of this video when it is a few seconds in, as a phone's
// player does, else the one before.
function back(app) {
  if (knownLength() && (video.time ?? 0) > RESTART_AFTER) seekTo(0)
  else step(app, -1)
}

const Icon = ({ d, size, flip }) => (
  <svg className={`w-[${size}px] h-[${size}px]`} viewBox="0 0 24 24">
    {flip ? <path fill="currentColor" d={d} transform="translate(24 0) scale(-1 1)" /> : <path fill="currentColor" d={d} />}
  </svg>
)
const ICONS = {
  play: 'M8 5v14l11-7z',
  pause: 'M6 5h4v14H6zM14 5h4v14h-4z',
  next: 'M6 18l8.5-6L6 6v12zM16 6v12h2V6h-2z',
  previous: 'M6 6h2v12H6zm3.5 6l8.5 6V6z',
  replay: 'M12 5V1L7 6l5 5V7c3.31 0 6 2.69 6 6s-2.69 6-6 6-6-2.69-6-6H4c0 4.42 3.58 8 8 8s8-3.58 8-8-3.58-8-8-8z',
  list: 'M3 13h2v-2H3v2zm0 4h2v-2H3v2zm0-8h2V7H3v2zm4 4h14v-2H7v2zm0 4h14v-2H7v2zM7 7v2h14V7H7z',
  close: 'M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z',
}

function Button({ icon, size, onClick, flip, label, strong }) {
  return (
    <div
      className={`relative flex items-center justify-center w-[${size * 2}px] h-[${size * 2}px] rounded-full ${strong ? 'bg-white/25' : 'bg-white/10'} active:bg-white/40 text-white`}
      onClick={onClick}
    >
      <Icon d={ICONS[icon]} size={size} flip={flip} />
      {label ? (
        // In the circle of the arrow: its middle is (12, 13) of the icon's 24.
        <span className={`absolute left-0 top-[${Math.round(size * 1.04 - Math.max(7, Math.round(size * 0.33)) * 0.62)}px] w-full text-center text-[${Math.max(7, Math.round(size * 0.33))}px] font-bold`}>
          {label}
        </span>
      ) : null}
    </div>
  )
}

function Message({ title, text, k }) {
  return (
    <div className="w-full h-full flex flex-col items-center justify-center bg-black text-white gap-[8px]">
      <span className={`text-[${Math.round(22 * k)}px] font-bold`}>{title}</span>
      <span className={`text-[${Math.round(15 * k)}px] text-white/70 text-center px-[24px]`}>{text}</span>
    </div>
  )
}

function List({ app, k }) {
  const list = order.length ? order : files
  const row = Math.round(44 * k)
  return (
    <div className="w-full h-full flex flex-col bg-neutral-900 text-white">
      <div className={`flex items-center gap-[12px] h-[${Math.round(56 * k)}px] px-[14px] shrink-0 bg-black`}>
        <span className={`flex-1 truncate text-[${Math.round(18 * k)}px] font-bold`}>
          {`${folderOf(app) || 'Assets'} · ${files.length} video${files.length === 1 ? '' : 's'}`}
        </span>
        <Button icon="close" size={Math.round(16 * k)} onClick={() => { view = 'player'; showControls() }} />
      </div>
      <div className="flex-1 overflow-y-auto">
        {list.map((file) => (
          <div
            className={`flex items-center gap-[10px] h-[${row}px] px-[16px] border-b border-white/10 ${file === current ? 'bg-sky-700' : 'active:bg-white/20'}`}
            onClick={() => { play(app, file, 0); view = 'player'; showControls() }}
          >
            <span className={`flex-1 truncate text-[${Math.round(15 * k)}px] ${failed[file] ? 'text-white/40' : ''}`}>
              {file.slice(folderOf(app) ? folderOf(app).length + 1 : 0)}
            </span>
            {failed[file] ? <span className={`text-[${Math.round(12 * k)}px] text-red-300`}>cannot play</span> : null}
          </div>
        ))}
      </div>
    </div>
  )
}

// The bar: a finger on it moves the knob and says where it will go, and the
// video goes there when it lifts (each seek starts the decoder again).
function SeekBar({ k }) {
  const duration = video.duration
  const along = scrub ?? Math.min(video.time ?? 0, duration) / duration
  const percent = Math.round(along * 1000) / 10
  const knob = Math.max(10, Math.round(16 * k))
  const track = Math.max(3, Math.round(5 * k))
  const height = Math.max(24, Math.round(36 * k))
  const at = (e) => Math.max(0, Math.min(1, e.localX / Math.max(e.width, 1)))
  return (
    <div
      className={`relative w-full h-[${height}px]`}
      onPointerDown={(e) => { scrub = at(e); showControls() }}
      onPointerMove={(e) => {
        if (!e.buttons || scrub === null) return false
        scrub = at(e)
        showControls()
      }}
      onPointerUp={(e) => {
        if (scrub === null) return
        const to = at(e) * duration
        scrub = null
        seekTo(to)
        showControls()
      }}
    >
      <div className={`absolute left-0 top-[${Math.round((height - track) / 2)}px] w-full h-[${track}px] rounded-full bg-white/25`}>
        <div className={`h-full w-[${percent}%] rounded-full bg-sky-400`} />
      </div>
      <div
        className={`absolute top-[${Math.round((height - knob) / 2)}px] left-[${percent}%] -ml-[${Math.round(knob / 2)}px] w-[${knob}px] h-[${knob}px] rounded-full ${scrub !== null ? 'bg-white' : 'bg-sky-300'}`}
      />
    </div>
  )
}

function Controls({ app, k }) {
  const icon = Math.round(22 * k)
  const known = knownLength()
  const duration = known ? video.duration : -1
  const time = scrub !== null && known ? scrub * duration : video.time ?? 0
  const list = playable()
  return (
    <div className="absolute left-0 top-0 w-full h-full flex flex-col justify-between">
      <div className={`flex items-center gap-[10px] px-[14px] h-[${Math.round(48 * k)}px] bg-black/60 text-white`}>
        <span className={`flex-1 truncate text-[${Math.round(16 * k)}px] font-bold`}>{baseName(current)}</span>
        <span className={`text-[${Math.round(13 * k)}px] text-white/70`}>
          {`${Math.max(1, list.indexOf(current) + 1)} of ${list.length}`}
        </span>
        <Button icon="list" size={Math.round(16 * k)} onClick={() => { view = 'list' }} />
      </div>
      <div className={`flex items-center justify-center gap-[${Math.round(18 * k)}px]`}>
        <Button icon="previous" size={icon} onClick={() => { back(app); showControls() }} />
        {known ? (
          <Button icon="replay" size={icon} label={String(SKIP_SECONDS)} onClick={() => { skip(-SKIP_SECONDS, 'left'); showControls() }} />
        ) : null}
        <Button icon={paused ? 'play' : 'pause'} size={Math.round(icon * 1.5)} strong onClick={() => { togglePause(); showControls() }} />
        {known ? (
          <Button icon="replay" flip size={icon} label={String(SKIP_SECONDS)} onClick={() => { skip(SKIP_SECONDS, 'right'); showControls() }} />
        ) : null}
        <Button icon="next" size={icon} onClick={() => { step(app, 1); showControls() }} />
      </div>
      <div className={`flex flex-col px-[16px] pb-[${Math.round(10 * k)}px] pt-[${Math.round(6 * k)}px] bg-black/60 text-white`}>
        {known ? <SeekBar k={k} /> : null}
        <div className={`flex items-center text-[${Math.round(13 * k)}px] text-white/80`}>
          <span className="flex-1">{video.live ? 'Live' : clock(time)}</span>
          <span>{known ? `−${clock(Math.max(0, duration - time))}` : ''}</span>
        </div>
      </div>
    </div>
  )
}

// A skip says so on its side, as a phone's player does, for a moment.
function Flash({ k }) {
  if (!flash || Date.now() >= flash.until) return null
  const size = Math.round(28 * k)
  const where = flash.side === 'left' ? 'justify-start pl-[6%]' : 'justify-end pr-[6%]'
  return (
    <div className={`absolute left-0 top-0 w-full h-full flex items-center ${where}`}>
      <div className={`flex items-center justify-center min-w-[${size * 2}px] h-[${size * 2}px] px-[10px] rounded-full bg-black/50 text-white`}>
        <span className={`text-[${Math.round(18 * k)}px] font-bold`}>{flash.text}</span>
      </div>
    </div>
  )
}

export function get(app, context) {
  const width = context?.imageWidth ?? app.frame.width
  const height = context?.imageHeight ?? app.frame.height
  const k = Math.max(0.6, Math.min(1.6, Math.min(width / 800, height / 480) * 1.15))
  listFolder(app)
  if (!files.length) {
    return (
      <Message
        k={k}
        title={`No videos in “${folderOf(app) || 'the assets folder'}”`}
        text={`Copy video files (.mp4, .mkv, .webm, .mov) into the frame's assets folder, in ${folderOf(app) || 'its top'}/. The Files scene uploads them from the browser.`}
      />
    )
  }
  if (!current) {
    const spot = readSpot(app)
    if (spot.file && files.includes(spot.file)) {
      current = spot.file
      frameos.remember('start', Math.max(0, Number(spot.time) || 0))
    } else {
      play(app, playable()[0] ?? files[0], 0)
    }
  }
  if (view === 'list') return <List app={app} k={k} />

  const fit = app.state.fit === 'cover' ? 'cover' : 'contain'
  const playCurrent = () => {
    const v = frameos.video('player', {
      src: current,
      start: frameos.recall('start') ?? 0,
      loop: app.state.repeat === 'one',
      paused,
      fit,
      fps: Number(app.state.fps) || 30,
    })
    if (restartAt !== null) {
      frameos.seekVideo(v, restartAt)
      restartAt = null
    }
    return v
  }
  video = playCurrent()
  if (video.state === 'ended') {
    // The next one now, in this render: its first frame follows the last.
    step(app, 1)
    video = playCurrent()
  } else if (video.state === 'error') {
    if (video.id === 0 && /cannot play it|, not here/.test(video.error || '')) {
      // No video on this frame at all (an ESP32, the preview): say so once.
      return <Message k={k} title="Video does not play here" text={video.error} />
    }
    if (!failed[current]) {
      failed[current] = video.error || 'cannot play'
      failedAt = Date.now()
    }
    if (playable().length === 0) {
      return <Message k={k} title="None of these videos play" text={`${baseName(current)}: ${failed[current]}`} />
    }
    if (Date.now() - failedAt >= SKIP_FAILED_MS) {
      step(app, 1)
      video = playCurrent()
    } else {
      frameos.setNextSleep(SKIP_FAILED_MS / 1000)
      return <Message k={k} title={baseName(current)} text={`Cannot play it: ${failed[current]}. Next one in a moment.`} />
    }
  } else if (video.state === 'playing' && Date.now() - savedAt > 15000) {
    // Where it is, now and then: a restart goes on from about here.
    frameos.setState('spot', { file: current, time: video.time })
    savedAt = Date.now()
  }
  const controls = controlsShown()
  // Paused, nothing moves: one more render when the controls or a flash go.
  if (paused || video.state !== 'playing') {
    const until = Math.max(flash?.until ?? 0, controlsUntil)
    if (until > Date.now()) frameos.setNextSleep((until - Date.now()) / 1000 + 0.05)
  }
  return (
    <div
      className="relative w-full h-full bg-black"
      onClick={() => {
        // A tap on the picture: the controls, or away with them.
        if (controls && !paused) controlsUntil = 0
        else showControls()
      }}
      onDoubleClick={(e) => {
        // Its two taps came first; the side says which way.
        const along = e.localX / Math.max(e.width, 1)
        if (along < 1 / 3) skip(-SKIP_SECONDS, 'left')
        else if (along > 2 / 3) skip(SKIP_SECONDS, 'right')
        showControls()
      }}
      onSwipe={(e) => {
        if (e.direction === 'left') step(app, 1)
        else if (e.direction === 'right') back(app)
        else return
        showControls()
      }}
    >
      <img className={`w-full h-full object-${fit}`} src={video} />
      {video.state === 'loading' && !controls ? (
        <span className={`absolute left-[16px] bottom-[12px] text-[${Math.round(13 * k)}px] text-white/60`}>{baseName(current)}</span>
      ) : null}
      {controls ? <Controls app={app} k={k} /> : null}
      <Flash k={k} />
    </div>
  )
}

// The keys and the frame's back and forward (a swipe in from a touch
// screen's edge): the scene's own while it plays.
export function onEvent(app, context) {
  const p = context.payload || {}
  if (context.event === 'back' || context.event === 'forward') {
    if (!files.length || view !== 'player') return false
    if (context.event === 'back') back(app)
    else step(app, 1)
    showControls()
    return true
  }
  if (context.event !== 'keyDown' || p.ctrl || p.alt || p.meta || !files.length) return false
  const key = String(p.key || '')
  const code = String(p.code || '')
  if (view === 'list') {
    if (key === 'Escape' || key.toLowerCase() === 'l') {
      view = 'player'
      showControls()
      return true
    }
    return false
  }
  const lower = key.toLowerCase()
  if (code === 'ArrowLeft') skip(-SKIP_SECONDS, 'left')
  else if (code === 'ArrowRight') skip(SKIP_SECONDS, 'right')
  else if (key === ' ' || code === 'Space' || lower === 'k') togglePause()
  else if (lower === 'n' || code === 'PageDown') step(app, 1)
  else if (lower === 'p' || code === 'PageUp') back(app)
  else if (lower === 'l') view = 'list'
  else if (code === 'Home') seekTo(0)
  else if (/^[0-9]$/.test(key) && knownLength()) seekTo((Number(key) / 10) * video.duration)
  else return false
  showControls()
  return true
}
